using System;
using System.Collections.Generic;
using System.Linq;

public enum ServiceLifetime { Transient, Scoped, Singleton }

public class ServiceDescriptor
{
    public Type ServiceType { get; set; }
    public Type ImplementationType { get; set; }
    public ServiceLifetime Lifetime { get; set; }
}

public class MiniContainer
{
    private readonly List<ServiceDescriptor> _descriptors = new();

    public void Register(Type serviceType, Type implType, ServiceLifetime lifetime)
    {
        _descriptors.Add(new ServiceDescriptor { ServiceType = serviceType, ImplementationType = implType, Lifetime = lifetime });
    }

    public void ValidateCaptiveDependencies()
    {
        Console.WriteLine("[Audit] Menjalankan validasi container...");

        var scopedServices = _descriptors
            .Where(d => d.Lifetime == ServiceLifetime.Scoped)
            .Select(d => d.ServiceType)
            .ToHashSet();

        foreach (var singleton in _descriptors.Where(d => d.Lifetime == ServiceLifetime.Singleton))
        {
            var constructors = singleton.ImplementationType.GetConstructors();
            foreach (var ctor in constructors)
            {
                foreach (var param in ctor.GetParameters())
                {
                    if (scopedServices.Contains(param.ParameterType))
                    {
                        throw new InvalidOperationException(
                            $"Captive Dependency: Singleton '{singleton.ImplementationType.Name}' tidak boleh bergantung pada Scoped service '{param.ParameterType.Name}'!");
                    }
                }
            }
        }
    }
}

public interface IOrderRepository { }
public class SqlOrderRepository : IOrderRepository { }

public interface IEmailService { }
public class SmtpEmailService : IEmailService
{
    public SmtpEmailService(IOrderRepository repo) { }
}

public class Program
{
    public static void Main()
    {
        var container = new MiniContainer();
        container.Register(typeof(IOrderRepository), typeof(SqlOrderRepository), ServiceLifetime.Scoped);
        container.Register(typeof(IEmailService), typeof(SmtpEmailService), ServiceLifetime.Singleton);

        try
        {
            container.ValidateCaptiveDependencies();
            Console.WriteLine("Semua dependensi valid.");
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine($"[TERDETEKSI BUG]: {ex.Message}");
        }
    }
}
